//! TypeScript emitter: `interface`s and union types for the JSON wire form. Types only; the
//! codec is `JSON.parse` / `JSON.stringify`.

use crate::schema::{Def, EnumRepr, Field, Named, Schema, Ty, VariantKind};
use std::fmt::Write;

/// Emit TypeScript declarations for every definition in `schema`.
#[must_use]
pub fn typescript(schema: &Schema) -> String {
    let mut out = String::from(
        "// Generated by wirefold::facet::emit::typescript. Do not edit.\n//\n// Types for the JSON wire form: `JSON.parse(text) as X`. A 128-bit integer is a decimal string.\n",
    );
    for w in &schema.warnings {
        let _ = writeln!(out, "// warning: {w}");
    }
    for d in &schema.defs {
        out.push('\n');
        emit_def(&mut out, d);
    }
    out
}

fn ty(t: &Ty) -> String {
    match t {
        Ty::Null => "null".into(),
        Ty::Bool => "boolean".into(),
        Ty::Int { .. } | Ty::Float { .. } => "number".into(),
        Ty::BigInt { .. } | Ty::String => "string".into(),
        Ty::Option(i) => format!("{} | null", paren(i)),
        Ty::List(i) => format!("Array<{}>", ty(i)),
        Ty::Map(i) => format!("{{ [key: string]: {} }}", ty(i)),
        Ty::Tuple(items) => format!("[{}]", items.iter().map(ty).collect::<Vec<_>>().join(", ")),
        Ty::Ref(n) => n.clone(),
        Ty::Any => "unknown".into(),
    }
}

/// `ty` for use as one arm of a union.
fn paren(t: &Ty) -> String {
    ty(t)
}

fn is_ident(s: &str) -> bool {
    !s.is_empty()
        && !s.starts_with(|c: char| c.is_ascii_digit())
        && s.chars()
            .all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '$')
}

fn key(s: &str) -> String {
    if is_ident(s) {
        s.to_owned()
    } else {
        quote(s)
    }
}

fn quote(s: &str) -> String {
    let mut o = String::from("\"");
    for c in s.chars() {
        match c {
            '"' => o.push_str("\\\""),
            '\\' => o.push_str("\\\\"),
            '\n' => o.push_str("\\n"),
            c if (c as u32) < 0x20 => {
                let _ = write!(o, "\\u{:04x}", c as u32);
            }
            c => o.push(c),
        }
    }
    o.push('"');
    o
}

fn jsdoc(out: &mut String, lines: &[String], indent: &str) {
    match lines {
        [] => {}
        [one] => {
            let _ = writeln!(out, "{indent}/** {} */", one.replace("*/", "* /"));
        }
        many => {
            let _ = writeln!(out, "{indent}/**");
            for l in many {
                let _ = writeln!(out, "{indent} * {}", l.replace("*/", "* /"));
            }
            let _ = writeln!(out, "{indent} */");
        }
    }
}

fn members(fields: &[Field]) -> String {
    fields
        .iter()
        .map(|f| {
            format!(
                "{}{}: {}",
                key(&f.name),
                if f.optional() { "?" } else { "" },
                ty(&f.ty)
            )
        })
        .collect::<Vec<_>>()
        .join("; ")
}

fn emit_def(out: &mut String, d: &Named) {
    jsdoc(out, &d.doc, "");
    let name = &d.name;
    match &d.def {
        Def::Struct { fields } => {
            if fields.is_empty() {
                let _ = writeln!(out, "export interface {name} {{}}");
                return;
            }
            let _ = writeln!(out, "export interface {name} {{");
            for f in fields {
                jsdoc(out, &f.doc, "  ");
                let _ = writeln!(
                    out,
                    "  {}{}: {};",
                    key(&f.name),
                    if f.optional() { "?" } else { "" },
                    ty(&f.ty)
                );
            }
            out.push_str("}\n");
        }
        Def::Tuple { items } => {
            let _ = writeln!(
                out,
                "export type {name} = [{}];",
                items.iter().map(ty).collect::<Vec<_>>().join(", ")
            );
        }
        Def::Enum { repr, variants } => {
            let arms: Vec<String> = variants
                .iter()
                .map(|v| {
                    let k = quote(&v.name);
                    match (repr, &v.kind) {
                        (EnumRepr::External, VariantKind::Unit) => k,
                        (EnumRepr::External, VariantKind::Newtype(t)) => {
                            format!("{{ {}: {} }}", key(&v.name), ty(t))
                        }
                        (EnumRepr::External, VariantKind::Tuple(items)) => format!(
                            "{{ {}: [{}] }}",
                            key(&v.name),
                            items.iter().map(ty).collect::<Vec<_>>().join(", ")
                        ),
                        (EnumRepr::External, VariantKind::Struct(fields)) => {
                            format!("{{ {}: {{ {} }} }}", key(&v.name), members(fields))
                        }
                        (EnumRepr::Internal { tag }, VariantKind::Unit) => {
                            format!("{{ {}: {k} }}", key(tag))
                        }
                        (EnumRepr::Internal { tag }, VariantKind::Struct(fields)) => {
                            let rest = members(fields);
                            format!(
                                "{{ {}: {k}{}{rest} }}",
                                key(tag),
                                if rest.is_empty() { "" } else { "; " }
                            )
                        }
                        (EnumRepr::Internal { tag }, VariantKind::Newtype(t)) => {
                            format!("({{ {}: {k} }} & {})", key(tag), ty(t))
                        }
                        (EnumRepr::Internal { tag }, VariantKind::Tuple(_)) => {
                            format!(
                                "{{ {}: {k} }} /* tuple variants cannot be internally tagged */",
                                key(tag)
                            )
                        }
                        (EnumRepr::Adjacent { tag, .. }, VariantKind::Unit) => {
                            format!("{{ {}: {k} }}", key(tag))
                        }
                        (EnumRepr::Adjacent { tag, content }, kind) => {
                            let payload = match kind {
                                VariantKind::Newtype(t) => ty(t),
                                VariantKind::Tuple(items) => {
                                    format!(
                                        "[{}]",
                                        items.iter().map(ty).collect::<Vec<_>>().join(", ")
                                    )
                                }
                                VariantKind::Struct(fields) => format!("{{ {} }}", members(fields)),
                                VariantKind::Unit => "null".into(),
                            };
                            format!("{{ {}: {k}; {}: {payload} }}", key(tag), key(content))
                        }
                    }
                })
                .collect();
            if arms.is_empty() {
                let _ = writeln!(out, "export type {name} = never;");
            } else {
                let _ = writeln!(out, "export type {name} =\n  | {};", arms.join("\n  | "));
            }
        }
    }
}
